-- TPC-H Q17 (sf10), generated by qgen -d -s 10
-- tpch-dbgen commit 32f1c1b92d1664dba542e927d23d86ffa57aa253
-- normalized: dropped 'where rownum <= -1' (no row limit)
select
	sum(l_extendedprice) / 7.0 as avg_yearly
from
	lineitem,
	part
where
	p_partkey = l_partkey
	and p_brand = 'Brand#23'
	and p_container = 'MED BOX'
	and l_quantity < (
		select
			0.2 * avg(l_quantity)
		from
			lineitem
		where
			l_partkey = p_partkey
	);
